mapper.select:
select p.id,p.name,p.merchant_id,p.category_id,p.brand_id,p.main_image,p.status,p.deleted,b.name as brandName,c.name as categoryName,mp.shop_name as merchantName from product p left join merchant_profile mp on p.merchant_id = mp.id left join brand b on p.brand_id = b.id left join category c on p.category_id = c.id
and p.name like concat('%',#{dto.keyword},'%')
and p.category_id = #{dto.categoryId}
and p.status = #{dto.status}
order by p.create_time desc
